create temporary table enterprise_ids(name text primary key,id uuid default gen_random_uuid());
insert into enterprise_ids(name) values('employee'),('manager'),('outsider');
create temporary table enterprise_results(name text,passed boolean);
grant select on enterprise_ids to authenticated;grant select,insert on enterprise_results to authenticated;
insert into auth.users(id,aud,role,email,raw_user_meta_data) select id,'authenticated','authenticated',name||'-enterprise@example.invalid','{}' from enterprise_ids;
insert into public.profiles(id,name,role) select id,name,case when name='manager' then 'manager' else 'employee' end from enterprise_ids;
insert into private.settings(key,value) values('review_hash',encode(extensions.digest('enterprise-test-secret','sha256'),'hex')) on conflict(key) do update set value=excluded.value;
set role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='manager'),false);
select public.save_purchase_order('{"reference":"PO-TEST","supplier":"Enterprise Supplies","receipt_reference":"GRN-TEST","items":[{"description":"Paper","quantity":10,"unit_price":50,"received":6}]}');
insert into enterprise_results values('Manager saves an order and goods receipt',(select count(*)=1 from public.purchase_orders));
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='employee'),false);
do $$declare blocked boolean:=false; row public.invoices; duplicate public.invoices; a jsonb; input jsonb;
begin
 insert into enterprise_results values('Unrelated orders are hidden from employee',(select count(*)=0 from public.purchase_orders));
 begin perform public.save_purchase_order('{"reference":"PO-FORGED"}');exception when others then blocked:=true;end;
 insert into enterprise_results values('Employee cannot create or edit orders',blocked);
 input:='{"supplier":"Enterprise Supplies","invoice_number":"ENTERPRISE-001","invoice_date":"2026-10-01","due_date":"2026-11-01","category":"Other","items":[{"description":"Paper","quantity":10,"unit_price":50}],"tax":0,"total":500,"notes":"test"}';
 row:=public.create_invoice(input,gen_random_uuid());perform public.set_invoice_matching(row.id,'two_way','PO-TEST');
 insert into enterprise_results values('PO details remain manager-only while assessment works',(select count(*)=0 from public.purchase_orders));
 a:=public.assess_invoice(row.id);insert into enterprise_results values('Two-way matches despite receipt shortage',not (a->>'blocked')::boolean);
 perform public.set_invoice_matching(row.id,'three_way','PO-TEST');a:=public.assess_invoice(row.id);
 insert into enterprise_results values('Three-way blocks receipt shortage',(a->>'blocked')::boolean and (a->>'score')::int=60);
 blocked:=false;begin perform public.set_invoice_matching(row.id,'two_way','PO-TEST');exception when others then blocked:=true;end;
 insert into enterprise_results values('Employee cannot weaken three-way matching',blocked);
 row:=public.start_review(row.id);row:=public.finish_review(row.id,row.run_id,'enterprise-test-secret','{"mode":"rules","summary":"test","tokens":0}');
 insert into enterprise_results values('Arithmetic review remains independent',row.status='pending_approval');
 a:=public.record_exception(row.id,'enterprise-test-secret','','rules');insert into enterprise_results values('Exception agent creates open case',(select status='open' from public.exception_cases where invoice_id=row.id));
 blocked:=false;begin perform public.record_exception(row.id,'forged','forged plan','ai');exception when others then blocked:=true;end;
 insert into enterprise_results values('Browser cannot forge exception plans',blocked);
 duplicate:=public.create_invoice(jsonb_set(input,'{invoice_number}','"enterprise 001"'),gen_random_uuid());a:=public.assess_invoice(duplicate.id);
 insert into enterprise_results values('Normalized duplicate catches punctuation and case',(a->>'blocked')::boolean and exists(select 1 from jsonb_array_elements(a->'signals') x where x->>'code'='duplicate_number'));
 blocked:=false;begin update public.invoices set status='approved' where id=row.id;exception when others then blocked:=true;end;
 insert into enterprise_results values('Direct invoice writes stay denied',blocked);
end $$;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='outsider'),false);
do $$declare blocked boolean:=false; candidate uuid;
begin
 select id into candidate from enterprise_ids where name='employee';
 insert into enterprise_results values('Outsider search cannot see invoices',(public.search_invoices('','',0,100000000,0)->>'total')::int=0);
 insert into enterprise_results values('Outsider cannot see unrelated PO',(select count(*)=0 from public.purchase_orders));
 insert into enterprise_results values('Outsider cannot read exception cases',(select count(*)=0 from public.exception_cases));
end $$;
reset role;
do $$declare id uuid; blocked boolean:=false;
begin
 select i.id into id from public.invoices i where invoice_number='ENTERPRISE-001';
 perform set_config('request.jwt.claim.sub',(select e.id::text from enterprise_ids e where name='outsider'),false);
 begin perform public.assess_invoice(id);exception when others then blocked:=true;end;
 insert into enterprise_results values('Explicit invoice ID cannot bypass authorization',blocked);
end $$;
set role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='manager'),false);
do $$declare row public.invoices; blocked boolean:=false;
begin
 select * into row from public.invoices where invoice_number='ENTERPRISE-001';
 begin perform public.decide_invoice(row.id,'approved','Verified by manager');exception when others then blocked:=true;end;
 insert into enterprise_results values('Database approval gate blocks matching and duplicates',blocked);
 -- Remove only the duplicate fixture by a legitimate rejection workflow.
 select * into row from public.invoices where invoice_number='enterprise 001';row:=public.start_review(row.id);row:=public.finish_review(row.id,row.run_id,'enterprise-test-secret','{"mode":"rules","summary":"test","tokens":0}');
 perform public.decide_invoice(row.id,'rejected','Duplicate submission confirmed in test');
 perform public.save_purchase_order('{"reference":"PO-TEST","supplier":"Enterprise Supplies","receipt_reference":"GRN-TEST","items":[{"description":"Paper","quantity":10,"unit_price":50,"received":10}]}');
 select * into row from public.invoices where invoice_number='ENTERPRISE-001';
 insert into enterprise_results values('Receipt update automatically rechecks exception case',(select status='resolved' from public.exception_cases where invoice_id=row.id));
 insert into enterprise_results values('Corrected receipt and rejected duplicate clear blockers',not (public.assess_invoice(row.id)->>'blocked')::boolean);
 perform public.record_exception(row.id,'enterprise-test-secret','','rules');
 insert into enterprise_results values('Exception case resolves after evidence passes',(select status='resolved' from public.exception_cases where invoice_id=row.id));
 perform public.decide_invoice(row.id,'approved','Purchase order and receipt checked');
 insert into enterprise_results values('Manager can approve after resolving exceptions',(select status='approved' from public.invoices where id=row.id));
 blocked:=false;begin perform public.save_purchase_order('{"reference":"BAD-PO","supplier":"Enterprise Supplies","receipt_reference":"","items":[{"description":"Paper","quantity":1,"unit_price":2,"received":1}]}');exception when others then blocked:=true;end;
 insert into enterprise_results values('Received goods require receipt reference',blocked);
end $$;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='employee'),false);
do $$declare row public.invoices; blocked boolean:=false;
begin
 row:=public.create_invoice('{"supplier":"Enterprise Supplies","invoice_number":"PARTIAL-002","invoice_date":"2026-10-02","due_date":"2026-11-01","category":"Other","items":[{"description":"Paper","quantity":1,"unit_price":50}],"tax":0,"total":50,"notes":"test"}',gen_random_uuid());
 perform public.set_invoice_matching(row.id,'two_way','PO-TEST');
 insert into enterprise_results values('Previously approved quantities prevent PO overbilling',(public.assess_invoice(row.id)->>'blocked')::boolean);
 for n in 1..20 loop perform public.reserve_assistant();end loop;
 begin perform public.reserve_assistant();exception when others then blocked:=true;end;
 insert into enterprise_results values('Assistant has an enforced 20-call daily budget',blocked);
end $$;
reset role;
-- Scale fixture: ordinary rows remain invisible to outsider and search is paginated beyond API row cap.
insert into public.invoices(client_id,created_by,supplier,invoice_number,invoice_date,due_date,category,items,tax,total,status)
select gen_random_uuid(),(select id from enterprise_ids where name='employee'),'Scale Supplier','SCALE-'||n,'2026-10-01','2026-11-01','Other','[{"description":"Test","quantity":1,"unit_price":10}]',0,10,'submitted' from generate_series(1,2000) n;
set role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='employee'),false);
insert into enterprise_results values('Search counts all 2,000 invoices',(public.search_invoices('Scale Supplier','',0,100000000,0)->>'total')::int=2000);
insert into enterprise_results values('Search returns at most 20 rows per page',jsonb_array_length(public.search_invoices('Scale Supplier','',0,100000000,0)->'invoices')=20);
insert into enterprise_results values('Search reaches invoices beyond the first 1,000',jsonb_array_length(public.search_invoices('Scale Supplier','',0,100000000,1500)->'invoices')=20);
insert into enterprise_results values('Search finds a specific invoice by number',(public.search_invoices('SCALE-1999','',0,100000000,0)->>'total')::int=1);
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='outsider'),false);
insert into enterprise_results values('Scale search still respects account visibility',(public.search_invoices('Scale Supplier','',0,100000000,0)->>'total')::int=0);
reset role;
set role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from enterprise_ids where name='employee'),false);
insert into enterprise_results values('Date filters narrow search correctly',(public.search_invoices('Scale Supplier','',0,100000000,0,'2026-11-01','2026-11-30')->>'total')::int=0);
